import{_ as r,a0 as p,w as u,s as d,ao as i,I as e,x as o,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"在 Mac OS X 系统中创建用于 Mac 的 Ubuntu USB 启动盘 | LCTT x X-CMD","titleTemplate":false,"description":"在 Mac OS X 系统中创建用于 Mac 的 Ubuntu USB 启动盘 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Mac OS X 系统中创建用于 Mac 的 Ubuntu USB 启动盘 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Mac OS X 系统中创建用于 Mac 的 Ubuntu USB 启动盘 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141205 How To Create A Bootable Ubuntu USB Drive For Mac In OS X","title":"在 Mac OS X 系统中创建用于 Mac 的 Ubuntu USB 启动盘","tag":"201501","desc":""},"relativePath":"201501/20141205 How To Create A Bootable Ubuntu USB Drive For Mac In OS X.md","filePath":"[post].md"}'),l={name:"201501/20141205 How To Create A Bootable Ubuntu USB Drive For Mac In OS X.md"};function S(b,t,U,m,f,c){const s=p("Link");return u(),d("div",null,[t[25]||(t[25]=i('<h1 id="在-mac-os-x-系统中创建用于-mac-的-ubuntu-usb-启动盘" tabindex="-1">在 Mac OS X 系统中创建用于 Mac 的 Ubuntu USB 启动盘 <a class="header-anchor" href="#在-mac-os-x-系统中创建用于-mac-的-ubuntu-usb-启动盘" aria-label="Permalink to “在 Mac OS X 系统中创建用于 Mac 的 Ubuntu USB 启动盘”">​</a></h1><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Create_bootable_Ubuntu_USB_Mac_OS_X.jpg" alt=""></p><p>上个月，在戴尔的服务中心丢失我的笔记本后，我买了一台 Macbook Air 笔记本。买回来后我首先做的一些事就是给机器装上双系统，使 Ubuntu Linux 和 Mac OS X 都可用。随后的文章我会介绍如何在 Macbook 上安装 Linux ,刚开始我们需要学习 <strong>如何在 Mac OS X 系统中创建用于 Mac 的 Ubuntu USB 启动盘</strong>。</p><p>在 Ubuntu 系统或 Windows 系统中创建可启动的 USB 是非常容易的，但在 Mac OS X 系统中就没这么简单了。这就是为什么 Ubuntu 的官方指南上，在 Mac 中安装 live Ubuntu 推荐使用光盘安装而不是 USB 的原因。考虑到我的 Macbook Air 既没有 CD 驱动也没有 DVD 驱动，所以我更愿意在 Mac OS X 下创建一个 live USB。</p><h3 id="在-mac-os-x-下创建可启动-usb-驱动盘" tabindex="-1">在 Mac OS X 下创建可启动 USB 驱动盘### <a class="header-anchor" href="#在-mac-os-x-下创建可启动-usb-驱动盘" aria-label="Permalink to “在 Mac OS X 下创建可启动 USB 驱动盘###”">​</a></h3><p>如前所述，在 Mac OS X 上创建对于像 Ubuntu 或任何其它可引导的操作系统这样的可启动 USB 盘是个比较麻烦的过程。但请别担心，按照下面的步骤一步一步操作就行。让我们就开始创建一个可启动的 USB 盘的操作吧：</p><h4 id="步骤-1-格式化-usb-驱动盘" tabindex="-1">步骤 1: 格式化 USB 驱动盘 <a class="header-anchor" href="#步骤-1-格式化-usb-驱动盘" aria-label="Permalink to “步骤 1: 格式化 USB 驱动盘”">​</a></h4>',7)),e("p",null,[t[1]||(t[1]=o("苹果是以它自定义的标准而闻名的，所以 Mac OS X 系统有自己的文件系统类型就毫不奇怪了，它的文件系统叫做 Mac OS 扩展或 ",-1)),a(s,{href:"http://en.wikipedia.org/wiki/HFS_Plus"},{default:n(()=>[...t[0]||(t[0]=[o("HFS 插件",-1)])]),_:1}),t[2]||(t[2]=o("。因此，您需要做的第一件事就是用 Mac OS 扩展文件系统来格式化您的 USB 驱动盘。",-1))]),t[26]||(t[26]=i('<p>要格式化 USB 盘，请先插入 USB 盘。从 Launchpad（在底部面板上的一个火箭形状的图标）上前往<strong>磁盘工具</strong>应用程序。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Disk_Utility_Mac.jpg" alt=""></p><ul><li>在磁盘工具中，从左手边的面板上选择你的 USB 盘来格式化。</li><li>点击右边面板的<strong>分区</strong>标签。</li><li>从下拉菜单中，选择 <strong>1 分区</strong>。</li><li>给这驱动盘起个您想要的名字。</li><li>接下来，切换分区格式为<strong>格式化成 Mac OS 扩展 (日志型)</strong></li></ul><p>下面的截屏将会对您有所帮助。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Format_Usb_Mac_4.jpg" alt=""></p><p>在我们开始真正格式化 USB 盘之前这是唯一一件要做的操作。点击在右边面板的选项按纽，要确保分区的模式是 <strong>GUID 分区表</strong>形式的。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Format_Usb_Mac_2.jpg" alt=""></p><p>当所有都已经设置完了后，仅仅只需点击<strong>应用</strong>按纽。它会弹出一个要格式化 USB 驱动盘的警告消息，当然是要点击分区按纽来格式化 USB 驱动盘拉。</p><h4 id="步骤-2-下载-ubuntu" tabindex="-1">步骤 2: 下载 Ubuntu <a class="header-anchor" href="#步骤-2-下载-ubuntu" aria-label="Permalink to “步骤 2: 下载 Ubuntu”">​</a></h4>',9)),e("p",null,[t[4]||(t[4]=o("当然，您需要下载 Ubuntu 桌面版本的 ISO 镜像文件。链接到",-1)),a(s,{href:"http://www.ubuntu.com/download/desktop"},{default:n(()=>[...t[3]||(t[3]=[o(" Ubuntu 官网去下载您喜欢的 Ubuntu 桌面版本系统",-1)])]),_:1}),t[5]||(t[5]=o("。因为您使用的是 Macbook Air，我建议您下载 64 位版本中的一款。Ubuntu 14.04 是最新的 LTS 版本，我建议您们使用它。",-1))]),t[27]||(t[27]=e("h4",{id:"步骤-3-把-iso-格式转成-img-格式",tabindex:"-1"},[o("步骤 3: 把 ISO 格式转成 IMG 格式 "),e("a",{class:"header-anchor",href:"#步骤-3-把-iso-格式转成-img-格式","aria-label":"Permalink to “步骤 3: 把 ISO 格式转成 IMG 格式”"},"​")],-1)),e("p",null,[t[7]||(t[7]=o("您下载的文件是 ISO 格式的，但我们需要它是 IMG 格式的，使用 ",-1)),a(s,{href:"https://developer.apple.com/library/mac/documentation/Darwin/Reference/ManPages/man1/hdiutil.1.html"},{default:n(()=>[...t[6]||(t[6]=[o("hdiutil",-1)])]),_:1}),t[8]||(t[8]=o(" 命令工具就可以很容易的转换。打开终端，也可以从 Launchpad 或 Spotlight 中打开，然后使用如下的命令就可以把 ISO 格式的转换成 IMG 格式的了:",-1))]),t[28]||(t[28]=i(`<pre><code>hdiutil convert -format UDRW -o ~/Path-to-IMG-file ~/Path-to-ISO-file
</code></pre><p>通常下载的文件会在 ~/Downloads 目录下。所以在我的系统来，输入的命令是:</p><pre><code>hdiutil convert -format UDRW -o ~/Downloads/ubuntu-14.10-desktop-amd64 ~/Downloads/ubuntu-14.10-desktop-amd64.iso
</code></pre><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/ISO_to_IMG_Convert_Mac_OS_X.jpeg" alt=""></p><p>您可能已经注意到我并没有新转换出的文件加上 IMG 后缀。这是没问题的，因为后缀只是个标志，重要的是文件类型并不是文件的扩展名。转换出来的文件可能会被 Mac OS X 系统自动加上个 .dmg 后缀。别担心，这是正常的。</p><h4 id="步骤-4-获得-usb-盘的设备号" tabindex="-1">步骤 4: 获得 USB 盘的设备号 <a class="header-anchor" href="#步骤-4-获得-usb-盘的设备号" aria-label="Permalink to “步骤 4: 获得 USB 盘的设备号”">​</a></h4><p>接下来的事情就是获得 USB 盘的设备号。在终端中运行如下命令：</p><pre><code>diskutil list
</code></pre><p>它会列出系统中当前可用的所有‘磁盘’信息。从它的大小上您应该能识别出此 USB 盘。为了避免混淆，我建议您只插入一个 USB 盘。我的示例中，设置号是 2 （一个大小为 8G 的 USB）: /dev/disk2</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Create_bootable_USB_Mac_OSX.jpeg" alt=""></p><p>当得到设备号后，运行如下命令：</p><pre><code>diskutil unmountDisk /dev/diskN
</code></pre><p>这儿的 N 就是前面您得到的 USB 的设备号。所以，我的示例中，上面的命令就变成：</p><pre><code>diskutil unmountDisk /dev/disk2
</code></pre><p>执行结果应该是：<strong>成功的卸载 disk2 上的所有卷</strong>。</p><h4 id="步骤-5-在-mac-os-x-中创建可启动的-usb-驱动盘" tabindex="-1">步骤 5: 在 Mac OS X 中创建可启动的 USB 驱动盘#### <a class="header-anchor" href="#步骤-5-在-mac-os-x-中创建可启动的-usb-驱动盘" aria-label="Permalink to “步骤 5: 在 Mac OS X 中创建可启动的 USB 驱动盘####”">​</a></h4>`,16)),e("p",null,[t[10]||(t[10]=o("终于我们只有创建可启动的 USB 盘这最后一步了。我们会使用 ",-1)),a(s,{href:"http://en.wikipedia.org/wiki/Dd_%28Unix%29"},{default:n(()=>[...t[9]||(t[9]=[o("dd 命令",-1)])]),_:1}),t[11]||(t[11]=o("，它非常的强大，必须得小心使用。因此，一定要记得您 USB 驱动盘的正确设备号，要不然会使 Mac OS X 系统崩溃。在终端中使用如下命令:",-1))]),t[29]||(t[29]=i(`<pre><code>sudo dd if=/Path-to-IMG-DMG-file of=/dev/rdiskN bs=1m
</code></pre><p>这儿我们使用 dd (拷贝和转换) 来把 IMG 输入文件 (if) 拷贝和转换到 磁盘 N 中。我希望您还记得在步骤 3 中已经生成的 IMG 文件的存放位置。对我的机器来说，命令如下所示：</p><pre><code>sudo dd if=~/Downloads/ubuntu-14.10-desktop-amd64.dmg of=/dev/rdisk2 bs=1m
</code></pre><p>我们用超级用户权限（sudo）来运行上面的命令，还需要您输入密码。跟 Linux 中类似，您从键盘中输入密码时，将看不到任何星号或显示的提示，不用担心，这是 Unix 终端的习惯。</p><p>甚至在您输入完密码后，<strong>您都不会看到立即的输出，这是正常的</strong>。需要一小会儿时间才会处理完成。</p><h4 id="步骤-6-完成可启动-usb-驱动盘的整个处理过程" tabindex="-1">步骤 6: 完成可启动 USB 驱动盘的整个处理过程 <a class="header-anchor" href="#步骤-6-完成可启动-usb-驱动盘的整个处理过程" aria-label="Permalink to “步骤 6: 完成可启动 USB 驱动盘的整个处理过程”">​</a></h4><p>一旦 DD 命令处理完成，会弹出一个对话框：<strong>您插入的磁盘在这机器上不可读</strong>。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Bootable_USB_3.png" alt=""></p><p>别惊慌，一切正常。只是<strong>现在不要点击初始化、忽略或弹出按纽</strong>。回到终端，您会看到最新处理完成的一些信息。我的机器中显示如下：</p><blockquote><p>1109+1 records in</p><p>1109+1 records out</p><p>1162936320 bytes transferred in 77.611025 secs (14984164 bytes/sec)</p></blockquote><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Create_bootable_USB_Mac_OSX_1.jpeg" alt=""></p><p>现在，在终端中使用如下命令来弹出我们的 USB 驱动盘：</p><pre><code>diskutil eject /dev/diskN
</code></pre><p>N 当然指的是我们前面使用过的设备号，在我的示例中是 2 ：</p><pre><code>diskutil eject /dev/disk2
</code></pre><p>一旦弹出，点击前面出现那对话框上的<strong>忽略</strong>按纽。现在您的可启动 USB 磁盘已经创建好了，把它拔下来吧。</p><h4 id="步骤-7-检查您新创建的可启动-usb-盘" tabindex="-1">步骤 7: 检查您新创建的可启动 USB 盘 <a class="header-anchor" href="#步骤-7-检查您新创建的可启动-usb-盘" aria-label="Permalink to “步骤 7: 检查您新创建的可启动 USB 盘”">​</a></h4><p>一旦您在 Mac OS X 中完成了创建一个 live USB 这么重大的任务，是时候测试您的新成果了。</p><ul><li>插入可启动 USB 盘，重启系统。</li><li>在苹果启动的时候，一直按着 option （或 alt）键。</li><li>这会引导您进入启动时需要访问的可使用磁盘界面。我假设您知道接下来的操作步骤。</li></ul><p>对我机器来说它显示了两个 EFI 启动盘：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Ubuntu_boot_USB_Mac_OSX_1.jpeg" alt=""></p><p>我选择第一个，然后它就会直接进入 Grub 界面：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Ubuntu_boot_USB_Mac_OSX.jpeg" alt=""></p><p>我希望这篇教程对您想要在 Mac OS X 下创建可启动的 Ubuntu 系统 USB 驱动盘有所帮助。在接下来的一篇文章中您会学到怎么样安装 OS X 和 Ubuntu 双系统。请继续关注。</p><hr>`,25)),e("p",null,[t[13]||(t[13]=o("via: ",-1)),a(s,{href:"http://itsfoss.com/create-bootable-ubuntu-usb-drive-mac-os/"},{default:n(()=>[...t[12]||(t[12]=[o("http://itsfoss.com/create-bootable-ubuntu-usb-drive-mac-os/",-1)])]),_:1})]),e("p",null,[t[17]||(t[17]=o("作者：",-1)),a(s,{href:"http://itsfoss.com/author/Abhishek/"},{default:n(()=>[...t[14]||(t[14]=[o("Abhishek",-1)])]),_:1}),t[18]||(t[18]=o(" 译者：",-1)),a(s,{href:"https://github.com/runningwater"},{default:n(()=>[...t[15]||(t[15]=[o("runningwater",-1)])]),_:1}),t[19]||(t[19]=o(" 校对：",-1)),a(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[16]||(t[16]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[22]||(t[22]=o("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[20]||(t[20]=[o("LCTT",-1)])]),_:1}),t[23]||(t[23]=o(" 原创翻译，",-1)),a(s,{href:"http://linux.cn/"},{default:n(()=>[...t[21]||(t[21]=[o("Linux中国",-1)])]),_:1}),t[24]||(t[24]=o(" 荣誉推出",-1))])])}const B=r(l,[["render",S]]);export{g as __pageData,B as default};
